from AlgorithmImports import *

class TradingAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.sma_spy = self.SMA(self.spy, 20, Resolution.Daily)
        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_consecutive_red_days = 0
        self.aapl_prev_close = None
        self.rsi_aapl = self.RSI(self.aapl, 14, Resolution.Daily)

    def OnData(self, data):
        if not all(self.Securities[sym].HasData for sym in self.symbols):
            return

        spy_close = self.Securities[self.spy].Close
        aapl_close = self.Securities[self.aapl].Close

        # Sells
        if self.sma_spy.IsReady:
            current_sma = self.sma_spy.Current.Value
            if self.spy_prev_sma is not None and self.spy_prev_close is not None:
                if self.spy_prev_close >= self.spy_prev_sma and spy_close < current_sma:
                    if self.Portfolio[self.spy].Quantity > 0:
                        self.Liquidate(self.spy)

        if self.rsi_aapl.IsReady:
            if self.rsi_aapl.Current.Value > 60 and self.Portfolio[self.aapl].Quantity > 0:
                self.Liquidate(self.aapl)

        # Buys
        if self.sma_spy.IsReady:
            current_sma = self.sma_spy.Current.Value
            if self.spy_prev_sma is not None and self.spy_prev_close is not None:
                if self.spy_prev_close <= self.spy_prev_sma and spy_close > current_sma:
                    if self.Portfolio[self.spy].Quantity == 0:
                        self.SetHoldings(self.spy, 0.40)

            self.spy_prev_close = spy_close
            self.spy_prev_sma = current_sma

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_consecutive_red_days += 1
            else:
                self.aapl_consecutive_red_days = 0

        if self.aapl_consecutive_red_days >= 3:
            if self.Portfolio[self.aapl].Quantity == 0:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy(self.aapl, shares)

        self.aapl_prev_close = aapl_close

