from AlgorithmImportModuleBase import *

class QuantConnectAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.spy_closes = []
        self.aapl_closes = []

        self.sma_period = 20
        self.rsi_period = 14

    def OnData(self, data):
        for ticker in self.tickers:
            if not data.ContainsKey(ticker) or not data[ticker]:
                return

        spy_close = float(data["SPY"].Close)
        aapl_close = float(data["AAPL"].Close)

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        min_bars = max(self.sma_period + 1, self.rsi_period + 1)
        if len(self.spy_closes) < min_bars:
            return

        self.execute_strategy_a()
        self.execute_strategy_b()

    def execute_strategy_a(self):
        spy_close = self.spy_closes[-1]
        spy_close_prev = self.spy_closes[-2]

        sma_today = sum(self.spy_closes[-self.sma_period:]) / self.sma_period
        sma_prev = sum(self.spy_closes[-(self.sma_period+1):-1]) / self.sma_period

        if self.strategy_a_lot > 0:
            if spy_close_prev >= sma_prev and spy_close < sma_today:
                self.Sell("SPY", self.strategy_a_lot)
                self.strategy_a_lot = 0

        if self.strategy_a_lot == 0:
            if spy_close_prev <= sma_prev and spy_close > sma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment = portfolio_value * 0.4
                shares = int(investment / spy_close)
                if shares > 0:
                    self.Buy("SPY", shares)
                    self.strategy_a_lot = shares

    def execute_strategy_b(self):
        aapl_close = self.aapl_closes[-1]

        if self.strategy_b_lot > 0:
            rsi = self.calc_rsi()
            if rsi > 60:
                self.Sell("AAPL", self.strategy_b_lot)
                self.strategy_b_lot = 0

        if self.strategy_b_lot == 0:
            if self.is_red_for_n_days(3):
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy("AAPL", shares)
                        self.strategy_b_lot = shares

    def is_red_for_n_days(self, n):
        if len(self.aapl_closes) < n + 1:
            return False

        for i in range(-n, 0):
            if self.aapl_closes[i] >= self.aapl_closes[i-1]:
                return False
        return True

    def calc_rsi(self):
        if len(self.aapl_closes) < self.rsi_period + 1:
            return 50

        closes = self.aapl_closes[-(self.rsi_period+1):]

        gains = []
        losses = []

        for i in range(1, len(closes)):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains.append(change)
                losses.append(0)
            else:
                gains.append(0)
                losses.append(-change)

        avg_gain = sum(gains) / self.rsi_period
        avg_loss = sum(losses) / self.rsi_period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi

