from AlgorithmImports import *

class TwoSlotAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.closes = {ticker: RollingWindow[float](2) for ticker in self.tickers}
        self.consecutive_red_days = {ticker: 0 for ticker in self.tickers}

        self.spy_sma = SimpleMovingAverage(20)
        self.spy_sma_values = RollingWindow[float](2)

        self.aapl_rsi = RelativeStrengthIndex(14)

    def OnData(self, data):
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        for ticker in self.tickers:
            close = data[self.symbols[ticker]].Close
            self.closes[ticker].Add(close)

        for ticker in self.tickers:
            if self.closes[ticker].Count > 1:
                if self.closes[ticker][0] < self.closes[ticker][1]:
                    self.consecutive_red_days[ticker] += 1
                else:
                    self.consecutive_red_days[ticker] = 0

        spy_close = self.closes["SPY"][0]
        self.spy_sma.Update(self.Time, spy_close)
        if self.spy_sma.IsReady:
            self.spy_sma_values.Add(self.spy_sma.Current.Value)

        aapl_close = self.closes["AAPL"][0]
        self.aapl_rsi.Update(self.Time, aapl_close)

        self.evaluate_strategy_a()
        self.evaluate_strategy_b()

    def evaluate_strategy_a(self):
        if self.spy_sma_values.Count < 2:
            return

        today_close = self.closes["SPY"][0]
        yesterday_close = self.closes["SPY"][1]
        today_sma = self.spy_sma_values[0]
        yesterday_sma = self.spy_sma_values[1]

        current_qty = self.Portfolio[self.symbols["SPY"]].Quantity

        if current_qty > 0:
            if yesterday_close >= yesterday_sma and today_close < today_sma:
                self.MarketOrder(self.symbols["SPY"], -current_qty)
        elif current_qty == 0:
            if yesterday_close <= yesterday_sma and today_close > today_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                amount = portfolio_value * 0.4
                shares = int(amount / today_close)
                if shares > 0:
                    self.MarketOrder(self.symbols["SPY"], shares)

    def evaluate_strategy_b(self):
        if not self.aapl_rsi.IsReady:
            return

        rsi_value = self.aapl_rsi.Current.Value
        aapl_close = self.closes["AAPL"][0]

        current_qty = self.Portfolio[self.symbols["AAPL"]].Quantity

        if current_qty > 0:
            if rsi_value > 60:
                self.MarketOrder(self.symbols["AAPL"], -current_qty)
        elif current_qty == 0:
            if self.consecutive_red_days["AAPL"] >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares)

