from AlgorithmImport import *

class MyQCAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.equities = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.equities:
            self.AddEquity(ticker, Resolution.Daily)

        # Strategy A (SPY)
        self.spy_closes = []
        self.sma_period = 20
        self.spy_prev_close = None

        # Strategy B (AAPL)
        self.aapl_closes = []
        self.aapl_red_days = 0
        self.aapl_prev_close = None

    def OnData(self, data):
        for ticker in self.equities:
            if not data.ContainsKey(ticker):
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        # Strategy A (SPY) - need 21 bars for cross detection
        if len(self.spy_closes) >= self.sma_period + 1:
            sma_today = sum(self.spy_closes[-self.sma_period:]) / self.sma_period
            sma_yesterday = sum(self.spy_closes[-(self.sma_period+1):-1]) / self.sma_period

            spy_holdings = self.Portfolio["SPY"].Quantity

            if spy_holdings > 0:
                if self.spy_prev_close >= sma_yesterday and spy_close < sma_today:
                    self.Liquidate("SPY")

            if spy_holdings == 0:
                if self.spy_prev_close <= sma_yesterday and spy_close > sma_today:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    target_value = portfolio_value * 0.40
                    shares_to_buy = int(target_value / spy_close)
                    if shares_to_buy > 0:
                        self.Buy("SPY", shares_to_buy)

        # Strategy B (AAPL) - need 15 bars for RSI
        if len(self.aapl_closes) >= 15:
            rsi = self.calculate_rsi(self.aapl_closes, 14)

            aapl_holdings = self.Portfolio["AAPL"].Quantity

            if aapl_holdings > 0:
                if rsi > 60:
                    self.Liquidate("AAPL")

            if aapl_holdings == 0:
                if self.aapl_red_days >= 3:
                    cash = self.Portfolio.Cash
                    if cash >= 20000:
                        shares_to_buy = int(20000 / aapl_close)
                        if shares_to_buy > 0:
                            self.Buy("AAPL", shares_to_buy)

        self.aapl_prev_close = aapl_close
        self.spy_prev_close = spy_close

    def calculate_rsi(self, closes, period):
        if len(closes) < period + 1:
            return None

        gains = 0
        losses = 0
        for i in range(len(closes) - period, len(closes)):
            delta = closes[i] - closes[i-1]
            if delta > 0:
                gains += delta
            else:
                losses -= delta

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

