from AlgorithmImports import *

class LeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.spy_position = 0
        self.aapl_position = 0

        self.spy_ma_period = 50
        self.spy_closes = RollingWindow[float](self.spy_ma_period + 1)

        self.aapl_consecutive_red = 0
        self.aapl_closes = RollingWindow[float](15)

    def OnData(self, data):
        for ticker in self.tickers:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        spy_close = data[self.symbols["SPY"]].Close
        aapl_close = data[self.symbols["AAPL"]].Close

        self.spy_closes.Add(spy_close)
        self.aapl_closes.Add(aapl_close)

        if self.spy_closes.Count <= self.spy_ma_period:
            return
        if self.aapl_closes.Count < 15:
            return

        spy_closes_list = list(self.spy_closes)
        aapl_closes_list = list(self.aapl_closes)

        ma_today_spy = sum(spy_closes_list[0:self.spy_ma_period]) / self.spy_ma_period
        ma_yesterday_spy = sum(spy_closes_list[1:self.spy_ma_period+1]) / self.spy_ma_period

        curr_spy_close = spy_closes_list[0]
        prev_spy_close = spy_closes_list[1]

        aapl_rsi = self.CalculateRSI(aapl_closes_list, 14)

        curr_aapl_close = aapl_closes_list[0]
        prev_aapl_close = aapl_closes_list[1]

        if curr_aapl_close < prev_aapl_close:
            self.aapl_consecutive_red += 1
        else:
            self.aapl_consecutive_red = 0

        if self.spy_position > 0:
            if prev_spy_close >= ma_yesterday_spy and curr_spy_close < ma_today_spy:
                self.Liquidate(self.symbols["SPY"])
                self.spy_position = 0

        if self.spy_position == 0:
            if prev_spy_close <= ma_yesterday_spy and curr_spy_close > ma_today_spy:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares_to_buy = int(invest_amount / curr_spy_close)
                if shares_to_buy > 0:
                    self.Buy(self.symbols["SPY"], shares_to_buy)
                    self.spy_position = shares_to_buy

        if self.aapl_position > 0:
            if aapl_rsi > 60:
                self.Liquidate(self.symbols["AAPL"])
                self.aapl_position = 0

        if self.aapl_position == 0:
            if self.aapl_consecutive_red >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / curr_aapl_close)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols["AAPL"], shares_to_buy)
                        self.aapl_position = shares_to_buy

    def CalculateRSI(self, closes, period):
        if len(closes) < period + 1:
            return 50

        gains = 0
        losses = 0

        for i in range(1, period + 1):
            change = closes[i-1] - closes[i]
            if change > 0:
                gains += change
            else:
                losses += abs(change)

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

