        self.aapl_shares = 0
        self.spy_prev_price = None
        self.spy_prev_ma = None
        self.aapl_price_history = []

    def OnData(self, data):
        if not all(sym in data for sym in ["SPY", "AAPL", "IBM", "BAC", "AIG"]):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_price = data["SPY"].Close
        aapl_price = data["AAPL"].Close

        self.aapl_price_history.append(aapl_price)
        if len(self.aapl_price_history) > 4:
            self.aapl_price_history.pop(0)

        # Sells first
        if self.spy_shares > 0:
            if self.spy_prev_price is not None and self.spy_prev_ma is not None:
                current_ma = self.spy_sma.Current.Value
                if self.spy_prev_price >= self.spy_prev_ma and spy_price < current_ma:
                    self.Sell("SPY", self.spy_shares)
                    self.spy_shares = 0

        if self.aapl_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.Sell("AAPL", self.aapl_shares)
                self.aapl_shares = 0

        # Then buys
        if self.spy_shares == 0:
