from AlgorithmImports import *

class QuantConnectLeanAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to all tickers
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        # Track price history
        self.price_history = {ticker: [] for ticker in self.tickers}

        # Strategy A (SPY) state
        self.spy_lot = 0
        self.spy_close_prev = None
        self.spy_sma_prev = None

        # Strategy B (AAPL) state
        self.aapl_lot = 0

    def OnData(self, data):
        # Check if all tickers have data
        for ticker in self.tickers:
            if self.symbols[ticker] not in data.Bars:
                return

        # Update price history
        for ticker in self.tickers:
            bar = data.Bars[self.symbols[ticker]]
            self.price_history[ticker].append(bar.Close)

        # Check if we have enough history
        if len(self.price_history["SPY"]) < 101 or len(self.price_history["AAPL"]) < 15:
            return

        # Get current values
        spy_close = self.price_history["SPY"][-1]
        aapl_close = self.price_history["AAPL"][-1]
        spy_sma = sum(self.price_history["SPY"][-100:]) / 100
        aapl_rsi = self.CalculateRSI(self.price_history["AAPL"], 14)

        # Initialize previous values on first bar with enough history
        if self.spy_close_prev is None:
            self.spy_close_prev = self.price_history["SPY"][-2]
            self.spy_sma_prev = sum(self.price_history["SPY"][-101:-1]) / 100

        # Strategy A (SPY) - Evaluate SELL before BUY
        if self.spy_lot > 0:
            # Check if SPY close crosses below 100-day SMA
            if self.spy_close_prev >= self.spy_sma_prev and spy_close < spy_sma:
                # Sell entire lot
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

        if self.spy_lot == 0:
            # Check if SPY close crosses above 100-day SMA
            if self.spy_close_prev <= self.spy_sma_prev and spy_close > spy_sma:
                # Invest 40% of portfolio
                portfolio_value = self.Portfolio.TotalPortfolioValue
                amount = portfolio_value * 0.4
                shares = int(amount / spy_close)
                if shares > 0:
                    self.MarketOrder(self.symbols["SPY"], shares)
                    self.spy_lot = shares

        # Strategy B (AAPL) - Evaluate SELL before BUY
        if self.aapl_lot > 0:
            # Check if AAPL RSI closes above 60
            if aapl_rsi > 60:
                # Liquidate entire lot
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

        if self.aapl_lot == 0:
            # Check if AAPL has been red for 3 consecutive days
            red_days = 0
            for i in range(len(self.price_history["AAPL"]) - 1, 0, -1):
                if self.price_history["AAPL"][i] < self.price_history["AAPL"][i-1]:
                    red_days += 1
                else:
                    break

            if red_days >= 3:
                # Try to buy $20,000 if available
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares)
                        self.aapl_lot = shares

        # Update state for next bar
        self.spy_close_prev = spy_close
        self.spy_sma_prev = spy_sma

    def CalculateRSI(self, closes, period):
        if len(closes) < period + 1:
            return None

        recent = closes[-(period+1):]

        gains = 0.0
        losses = 0.0

        for i in range(1, len(recent)):
            change = recent[i] - recent[i-1]
            if change > 0:
                gains += change
            else:
                losses += abs(change)

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

from AlgorithmImports import *

class QuantConnectLean(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.spy_closes = []
        self.aapl_closes = []
        self.aapl_red_days = 0

    def OnData(self, data):
        for symbol in self.symbols:
            if symbol not in data:
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < 101 or len(self.aapl_closes) < 15:
            return

        spy_sma = sum(self.spy_closes[-100:]) / 100
        prev_spy_sma = sum(self.spy_closes[-101:-1]) / 100
        prev_spy_close = self.spy_closes[-2]
        prev_aapl_close = self.aapl_closes[-2]

        aapl_rsi = self._calculate_rsi(self.aapl_closes[-15:])

        spy_qty = self.Portfolio["SPY"].Quantity
        aapl_qty = self.Portfolio["AAPL"].Quantity

        if spy_qty > 0 and prev_spy_close > prev_spy_sma and spy_close <= spy_sma:
            self.MarketOrder("SPY", -spy_qty)

        if spy_qty == 0 and prev_spy_close <= prev_spy_sma and spy_close > spy_sma:
            portfolio_value = self.Portfolio.TotalPortfolioValue
            shares_to_buy = int(portfolio_value * 0.4 / spy_close)
            if shares_to_buy > 0:
                self.MarketOrder("SPY", shares_to_buy)

        if aapl_close < prev_aapl_close:
            self.aapl_red_days += 1
        else:
            self.aapl_red_days = 0

        if aapl_qty > 0 and aapl_rsi > 60:
            self.MarketOrder("AAPL", -aapl_qty)

        if aapl_qty == 0 and self.aapl_red_days >= 3:
            available_cash = self.Portfolio.Cash
            if available_cash >= 20000:
                shares_to_buy = int(20000 / aapl_close)
                if shares_to_buy > 0:
                    self.MarketOrder("AAPL", shares_to_buy)

    def _calculate_rsi(self, prices):
        if len(prices) < 2:
            return 50

        deltas = [prices[i] - prices[i-1] for i in range(1, len(prices))]
        gains = [d if d > 0 else 0 for d in deltas]
        losses = [-d if d < 0 else 0 for d in deltas]

        avg_gain = sum(gains) / len(gains)
        avg_loss = sum(losses) / len(losses)

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        return 100 - (100 / (1 + rs))

