        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < 101 or len(self.aapl_closes) < 15:
            return

        spy_sma = sum(self.spy_closes[-100:]) / 100
        prev_spy_sma = sum(self.spy_closes[-101:-1]) / 100
        prev_spy_close = self.spy_closes[-2]
        prev_aapl_close = self.aapl_closes[-2]

        aapl_rsi = self._calculate_rsi(self.aapl_closes[-15:])

        spy_qty = self.Portfolio["SPY"].Quantity
        aapl_qty = self.Portfolio["AAPL"].Quantity

        if spy_qty > 0 and prev_spy_close > prev_spy_sma and spy_close <= spy_sma:
            self.MarketOrder("SPY", -spy_qty)

        if spy_qty == 0 and prev_spy_close <= prev_spy_sma and spy_close > spy_sma:
            portfolio_value = self.Portfolio.TotalPortfolioValue
            shares_to_buy = int(portfolio_value * 0.4 / spy_close)
            if shares_to_buy > 0:
                self.MarketOrder("SPY", shares_to_buy)

        if aapl_close < prev_aapl_close:
            self.aapl_red_days += 1
        else:
