        spy_close = self.close_history["SPY"][-1]
        aapl_close = self.close_history["AAPL"][-1]

        spy_ma100 = np.mean(self.close_history["SPY"][-101:-1])
        aapl_rsi14 = self.CalculateRSI(self.close_history["AAPL"], 14)

        spy_prev_close = self.close_history["SPY"][-2]
        spy_prev_ma100 = np.mean(self.close_history["SPY"][-102:-2])

        spy_lot = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_lot = self.Portfolio[self.symbols["AAPL"]].Quantity

        if spy_lot > 0:
            if spy_prev_close >= spy_prev_ma100 and spy_close < spy_ma100:
                self.MarketOrder(self.symbols["SPY"], -spy_lot)

        if aapl_lot > 0:
            if aapl_rsi14 > 60:
                self.MarketOrder(self.symbols["AAPL"], -aapl_lot)

        if spy_lot == 0:
            if spy_prev_close <= spy_prev_ma100 and spy_close > spy_ma100:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.40
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder(self.symbols["SPY"], shares_to_buy)

        if aapl_lot == 0:
            aapl_history = self.close_history["AAPL"]
            if (aapl_history[-1] < aapl_history[-2] and
                aapl_history[-2] < aapl_history[-3] and
                aapl_history[-3] < aapl_history[-4]):
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares_to_buy)

    def CalculateRSI(self, closes, period):
        if len(closes) < period + 1:
            return None

        deltas = [closes[i] - closes[i-1] for i in range(1, len(closes))]
        gains = [d if d > 0 else 0 for d in deltas]
        losses = [-d if d < 0 else 0 for d in deltas]

        avg_gain = np.mean(gains[-period:])
        avg_loss = np.mean(losses[-period:])

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

