        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        for symbol in self.symbols:
            if symbol not in data or data[symbol].Close <= 0:
                return

        for symbol in self.symbols:
            self.price_data[symbol].append(data[symbol].Close)

        if len(self.price_data["SPY"]) < 101:
            return

        self.evaluate_sells()
        self.evaluate_buys()

    def evaluate_sells(self):
        if self.strategy_a_shares > 0:
            if self.crosses_below_sma(self.price_data["SPY"], 100):
                self.Sell("SPY", self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            rsi = self.calculate_rsi(self.price_data["AAPL"], 14)
            if rsi is not None and rsi > 60:
                self.Sell("AAPL", self.strategy_b_shares)
                self.strategy_b_shares = 0

    def evaluate_buys(self):
        if self.strategy_a_shares == 0:
            if self.crosses_above_sma(self.price_data["SPY"], 100):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.40
                spy_close = self.price_data["SPY"][-1]
                shares_to_buy = int(target_value / spy_close)

                if shares_to_buy > 0:
                    self.Buy("SPY", shares_to_buy)
                    self.strategy_a_shares = shares_to_buy

        if self.strategy_b_shares == 0:
            if self.is_red_for_n_days(self.price_data["AAPL"], 3):
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    aapl_close = self.price_data["AAPL"][-1]
                    shares_to_buy = int(20000 / aapl_close)

                    if shares_to_buy > 0:
                        self.Buy("AAPL", shares_to_buy)
                        self.strategy_b_shares = shares_to_buy

    def crosses_above_sma(self, prices, period):
        if len(prices) < period + 1:
            return False

        today_close = prices[-1]
        yesterday_close = prices[-2]

        today_sma = sum(prices[-period:]) / period
        yesterday_sma = sum(prices[-(period + 1):-1]) / period

        return yesterday_close <= yesterday_sma and today_close > today_sma

    def crosses_below_sma(self, prices, period):
        if len(prices) < period + 1:
            return False

        today_close = prices[-1]
        yesterday_close = prices[-2]

        today_sma = sum(prices[-period:]) / period
        yesterday_sma = sum(prices[-(period + 1):-1]) / period

        return yesterday_close >= yesterday_sma and today_close < today_sma

    def is_red_for_n_days(self, prices, n):
        if len(prices) < n + 1:
            return False

        red_count = 0
        for i in range(len(prices) - 1, max(len(prices) - n - 1, 0), -1):
            if prices[i] < prices[i - 1]:
                red_count += 1
            else:
                break

        return red_count >= n

    def calculate_rsi(self, prices, period):
        if len(prices) < period + 1:
            return None

        gains = 0
        losses = 0

        for i in range(len(prices) - period, len(prices)):
            change = prices[i] - prices[i - 1]
            if change > 0:
                gains += change
            elif change < 0:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

