class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        # Strategy symbols
        self.strategy_a_symbol = self.symbols["SPY"]
        self.strategy_b_symbol = self.symbols["AAPL"]

        # Indicators
        self.spy_sma100 = self.SMA(self.strategy_a_symbol, 100)
        self.aapl_rsi14 = self.RSI(self.strategy_b_symbol, 14)

        # History tracking
        self.spy_closes = []
        self.spy_smas = []
        self.aapl_closes = []
        self.aapl_red_days = 0

    def OnData(self, data):
        # Check all tickers have data
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        # Get prices
        spy_close = data[self.strategy_a_symbol].Close
        aapl_close = data[self.strategy_b_symbol].Close

        # Track closes
        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        # Compute red day counter continuously
        if len(self.aapl_closes) >= 2:
            if self.aapl_closes[-1] < self.aapl_closes[-2]:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0

        # Wait for indicators to be ready
        if not self.spy_sma100.IsReady or not self.aapl_rsi14.IsReady:
            return

        # Track SMA
        self.spy_smas.append(self.spy_sma100.Current.Value)

        # Evaluate sells before buys
        self.evaluate_sells()
        self.evaluate_buys()

    def evaluate_sells(self):
        # Strategy A: sell when SPY crosses below SMA100
        if self.Portfolio[self.strategy_a_symbol].Quantity > 0:
            if len(self.spy_closes) >= 2 and len(self.spy_smas) >= 2:
                if (self.spy_closes[-2] > self.spy_smas[-2] and 
                    self.spy_closes[-1] <= self.spy_smas[-1]):
                    qty = self.Portfolio[self.strategy_a_symbol].Quantity
                    self.MarketOrder(self.strategy_a_symbol, -qty)

        # Strategy B: sell when AAPL RSI > 60
        if self.Portfolio[self.strategy_b_symbol].Quantity > 0:
            if self.aapl_rsi14.Current.Value > 60:
                qty = self.Portfolio[self.strategy_b_symbol].Quantity
                self.MarketOrder(self.strategy_b_symbol, -qty)

    def evaluate_buys(self):
        # Strategy A: buy when SPY crosses above SMA100
        if self.Portfolio[self.strategy_a_symbol].Quantity == 0:
            if len(self.spy_closes) >= 2 and len(self.spy_smas) >= 2:
                if (self.spy_closes[-2] <= self.spy_smas[-2] and 
                    self.spy_closes[-1] > self.spy_smas[-1]):
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    shares = int(portfolio_value * 0.40 / self.spy_closes[-1])
                    if shares > 0:
                        self.MarketOrder(self.strategy_a_symbol, shares)

        # Strategy B: buy when AAPL red for 3+ days
        if self.Portfolio[self.strategy_b_symbol].Quantity == 0:
            if self.aapl_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / self.aapl_closes[-1])
                    if shares > 0:
                        self.MarketOrder(self.strategy_b_symbol, shares)

